const report = $input.first().json;
const expiring = report.expiring_plans || [];
const lowBalance = report.low_balance || [];
const staleOrders = report.stale_pending_orders || [];
const formatCny = (micros) => `¥${(Number(micros || 0) / 1000000).toFixed(2)}`;

const lines = [
  'CokeAI 每日待办',
  `3 天内到期套餐：${expiring.length}`,
  `余额低于 ¥2：${lowBalance.length}`,
  `超 2 小时未处理订单：${staleOrders.length}`,
  `可用模型：${report.ready_models ?? 0}`,
];

if (expiring.length) {
  lines.push('', '即将到期：');
  for (const item of expiring.slice(0, 10)) {
    lines.push(`- ${item.email}｜${item.plan || '无套餐'}｜${item.expires_at}`);
  }
}

if (lowBalance.length) {
  lines.push('', '低余额：');
  for (const item of lowBalance.slice(0, 10)) {
    lines.push(`- ${item.email}｜${formatCny(item.balance_micros)}`);
  }
}

if (staleOrders.length) {
  lines.push('', '待处理订单：');
  for (const item of staleOrders.slice(0, 10)) {
    lines.push(`- ${item.email}｜${formatCny(item.amount_micros)}｜${item.created_at}`);
  }
}

if (!$env.ALERT_WEBHOOK_URL) {
  return [];
}

const message = lines.join('\n');
return [{ json: { text: message, content: message } }];
